import { ok, fail } from './result.js';
import { getCustomer } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';

/**
 * Validate that a date string is in YYYY-MM-DD format and represents a real date.
 * @param {string} dateStr
 * @returns {boolean}
 */
function isValidDate(dateStr) {
  const match = /^\d{4}-\d{2}-\d{2}$/.test(dateStr);
  if (!match) return false;
  const date = new Date(`${dateStr}T00:00:00Z`);
  return date instanceof Date && !isNaN(date.getTime()) && date.toISOString().startsWith(dateStr);
}

function isValidDiscount(discountPercent) {
  return typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
}

/**
 * Calculate the total for a single line (qty * unitPrice).
 * @param {{ qty: number, unitPrice: number }}
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount for a single line.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }}
 * @returns {number}
 */
function lineDiscount(line) {
  const discount = lineTotal(line) * (line.discountPercent ?? 0) / 100;
  return Math.max(0, roundCents(discount));
}

/**
 * Calculate subtotal, discount, and total for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number }> }}
 * @returns {{ subtotal: number, discount: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const total = Math.max(0, subtotal - discount);
  return { subtotal, discount, total };
}

/**
 * Create a draft invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }}
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  const customer = getCustomer(customerId);
  if (!customer.ok) return customer;

  if (!isValidDate(issueDate)) {
    return fail('DATE_INVALID');
  }

  if (!Array.isArray(lines) || lines.length === 0) {
    return fail('NO_LINES');
  }

  const invoiceLines = [];
  for (const line of lines) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    const discountPercent = line.discountPercent ?? 0;
    if (!isValidDiscount(discountPercent)) {
      return fail('DISCOUNT_INVALID');
    }

    const product = getProduct(line.sku);
    if (!product.ok) return product;

    invoiceLines.push({
      sku: line.sku,
      name: product.value.name,
      qty: line.qty,
      unitPrice: product.value.unitPrice,
      vatRate: product.value.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
  });
}

/**
 * Add a line to an invoice or increase its quantity if it already exists.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} param
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  const discount = discountPercent ?? 0;
  if (!isValidDiscount(discount)) {
    return fail('DISCOUNT_INVALID');
  }

  const product = getProduct(sku);
  if (!product.ok) return product;

  const newLines = invoice.lines.map((line) => ({ ...line }));
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingLineIndex >= 0) {
    newLines[existingLineIndex].qty += qty;
  } else {
    newLines.push({
      sku,
      name: product.value.name,
      qty,
      unitPrice: product.value.unitPrice,
      vatRate: product.value.vatRate,
      discountPercent: discount,
    });
  }

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {string} sku
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) {
    return fail('LINE_NOT_FOUND');
  }

  if (invoice.lines.length === 1) {
    return fail('NO_LINES');
  }

  const newLines = invoice.lines.filter((_, i) => i !== lineIndex);

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Issue an invoice (change status from draft to issued and assign a number).
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {Array<string>} existingNumbers - Invoice numbers already used
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    number,
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: 'issued',
    lines: invoice.lines.map((line) => ({ ...line })),
  });
}

