test('addLine rejects invalid discountPercent', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 1, discountPercent: 150 });
  assert.deepEqual(result, { ok: false, error: 'DISCOUNT_INVALID' });
});

test('invoiceTotals returns subtotal, discount, and total', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const totals = invoiceTotals(invoice);
  assert.ok('subtotal' in totals);
  assert.ok('discount' in totals);
  assert.ok('total' in totals);
});

test('invoiceTotals calculates discount correctly', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
  }).value;

  // DES-HOUR: 2 * 8500 = 17000 cents
  // Discount: 17000 * 10 / 100 = 1700 cents
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 17000);
  assert.equal(totals.discount, 1700);
  assert.equal(totals.total, 15300);
});

test('invoiceTotals with multiple lines and different discounts', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 1, discountPercent: 20 },
    ],
  }).value;

  // DES-HOUR: 2 * 8500 = 17000, discount = 1700
  // DEV-HOUR: 1 * 9500 = 9500, discount = 1900
  // Total: 26500 - 3600 = 22900
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 26500);
  assert.equal(totals.discount, 3600);
  assert.equal(totals.total, 22900);
});

test('invoiceTotals clamps negative total at 0', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 100, vatRate: 21, discountPercent: 100 }],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 100);
  assert.equal(totals.discount, 100);
  assert.equal(totals.total, 0);
});

test('invoiceTotals with zero discount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 0 }],
  }).value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, totals.subtotal);
});

